// BUILD CONTEXT
const inp = $('Validate Input').item.json;
const rawSite = $input.first().json;
let site = Array.isArray(rawSite) ? rawSite[0] : (rawSite?.id ? rawSite : rawSite?.data?.[0]);
if (!site?.id) throw new Error('Site not found');

const SYSTEM_GITHUB_TOKEN = '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';
let githubToken = (site.access_token && site.access_token.trim()) || SYSTEM_GITHUB_TOKEN;

const repoMatch = (site.repo_url || '').match(/github\.com\/([^/]+)\/([^/]+)/);
if (!repoMatch) throw new Error('Invalid GitHub repo URL');

return [{
  json: {
    ...inp,
    site: { id: site.site_key || inp.siteId, uuid: site.id, name: site.name, repo_url: site.repo_url, branch: site.default_branch || 'main' },
