const ctx = $input.item.json;
const GEMINI_KEY = 'AIzaSyAOViIkqaut_PjUSNB49QjPk-_zWbOGvUw';
const siteId = ctx.site?.id;
const memoryContext = ctx.memoryContext || 'No prior context.';

const TOOLS = [
  { name: 'list_files', description: 'List files matching a glob pattern to understand project structure', parameters: { type: 'object', properties: { pattern: { type: 'string' } }, required: ['pattern'] } },
  { name: 'grep_search', description: 'Search for text inside files to find specific code', parameters: { type: 'object', properties: { pattern: { type: 'string' } }, required: ['pattern'] } },
  { name: 'read_file', description: 'Read file content to understand code', parameters: { type: 'object', properties: { path: { type: 'string' } }, required: ['path'] } }
];

const runTool = async (name, input) => {
  if (!siteId) return 'No project selected';
  if (name === 'list_files') {
    try {
      const r = await this.helpers.httpRequest({ method: 'POST', url: 'https://preview-orchestrator.fly.dev/preview/search', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ siteId, pattern: input.pattern || '**/*', type: 'glob' }), json: true, ignoreHttpStatusErrors: true });
      return (r?.matches || []).slice(0, 30).join('\n') || 'No files found';
    } catch (e) { return 'Error: ' + e.message; }
  }
  if (name === 'grep_search') {
    try {
      const r = await this.helpers.httpRequest({ method: 'POST', url: 'https://preview-orchestrator.fly.dev/preview/search', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ siteId, pattern: input.pattern, type: 'grep' }), json: true, ignoreHttpStatusErrors: true });
      return (r?.matches || []).slice(0, 20).join('\n') || 'No matches found';
    } catch (e) { return 'Error: ' + e.message; }
  }
  if (name === 'read_file') {
    try {
      const r = await this.helpers.httpRequest({ method: 'POST', url: 'https://preview-orchestrator.fly.dev/preview/read', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ siteId, filePath: input.path }), json: true, ignoreHttpStatusErrors: true });
      return r?.content ? r.content.slice(0, 4000) : 'File not found';
    } catch (e) { return 'Error: ' + e.message; }
  }
  return 'Unknown tool';
};

try {
  let contents = [{ role: 'user', parts: [{ text: `You are a helpful web development assistant with access to the project codebase. Use search tools to find information when needed.\n\nConversation history:\n${memoryContext}\n\nCurrent question: ${ctx.message}\n\nIf the question is about the codebase or project structure, use tools to find the answer. For general questions, answer directly.` }] }];
  let output = '';

  for (let i = 0; i < 4; i++) {
    const r = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash-exp:generateContent?key=' + GEMINI_KEY,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ contents, tools: siteId ? [{ functionDeclarations: TOOLS }] : undefined, generationConfig: { maxOutputTokens: 1000, temperature: 0.7 } }),
      timeout: 30000, json: true
    });
    const candidate = r.candidates?.[0];
    if (!candidate) { output = 'I can help you with that. Could you provide more details?'; break; }

    const functionCalls = candidate.content?.parts?.filter(p => p.functionCall) || [];
    if (functionCalls.length === 0) {
      output = candidate.content?.parts?.find(p => p.text)?.text || 'I can help you with that.';
      break;
    }

    const functionResponses = [];
    for (const fc of functionCalls) {
      const res = await runTool(fc.functionCall.name, fc.functionCall.args);
      functionResponses.push({ functionResponse: { name: fc.functionCall.name, response: { result: res } } });
    }
    contents.push({ role: 'model', parts: candidate.content.parts });
    contents.push({ role: 'user', parts: functionResponses });
  }

  console.log('💬 Question answered with search');
  return [{ json: { ...ctx, output, isDirectResponse: true, filesModified: [], filesCreated: [], filesDeleted: [], toolsUsed: ['search'], iterations: 0 } }];
} catch (e) {
  console.error('Question error:', e.message);
  return [{ json: { ...ctx, output: 'Sorry, I encountered an error: ' + e.message, isDirectResponse: true, filesModified: [], filesCreated: [], filesDeleted: [], toolsUsed: [], iterations: 0 } }];
}

