const runTool = async (name, args) => {
  if (!siteId) return 'Error: No siteId available';

  if (name === 'list_files_glob') {
    try {
      const r = await this.helpers.httpRequest({ method: 'POST', url: 'https://preview-orchestrator.fly.dev/preview/search', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ siteId, pattern: args.pattern, type: 'glob' }), json: true });
      const matches = r.matches || [];
      return matches.length > 0 ? matches.slice(0, 50).join('\n') + (matches.length > 50 ? '\n...truncated' : '') : 'No files found';
    } catch(e) { return 'Error: ' + e.message; }
