        tools: TOOLS,
        messages: messages
      }),
      timeout: 60000,
      json: true
    });

    const content = r.content || [];
    messages.push({ role: 'assistant', content });

    // Handle Tool Calls
    const toolUses = content.filter(c => c.type === 'tool_use');
    if (toolUses.length > 0) {
      const toolResults = [];
      for (const tu of toolUses) {
        console.log(`🔧 Planner Tool: ${tu.name}`, tu.input);
        if (tu.name === 'finish_plan') {
          plan = tu.input;
          break;
        }
        const result = await runTool(tu.name, tu.input);

        // Store read file content
        if (tu.name === 'read_file' && tu.input.path && !result.startsWith('Error')) {
             fileContents[tu.input.path] = result;
        }

        toolResults.push({ type: 'tool_result', tool_use_id: tu.id, content: result });
      }
      if (plan) break;
      messages.push({ role: 'user', content: toolResults });
    } else {
      // No tools used, maybe direct text response? Force finish if text looks like JSON?
