      const r = await this.helpers.httpRequest({ method: 'POST', url: 'https://preview-orchestrator.fly.dev/preview/search', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ siteId, pattern: input.pattern, type: 'grep' }), json: true, ignoreHttpStatusErrors: true });
      return (r?.matches || []).slice(0, 15).join('\n') || 'No matches';
