      const start = Math.max(0, (input.startLine || 1) - 1);
      const end = Math.min(lines.length, input.endLine || lines.length);
      return lines.slice(start, end).map((l, i) => (start + i + 1) + ': ' + l).join('\n').slice(0, 3000);
    } catch (e) { return 'Error: ' + e.message; }
  }

  if (name === 'write_file') {
